<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ApiError } from '@/api/client'; import { getAuditEvents, type AuditPayload } from '@/api/operations'; import { getSession } from '@/api/session';
import PaginationControls from '@/components/PaginationControls.vue';
const router = useRouter(); const data = ref<AuditPayload | null>(null); const error = ref<string | null>(null); const filters = reactive({ search: '', action: '', result: '', from: '', to: '' });
const load = async (page = 1) => { try { const session = await getSession(); if (session.active_role?.code !== 'administrador') { await router.replace('/panel'); return; } data.value = await getAuditEvents({ ...filters, page: String(page) }); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo cargar la auditoría.'; } };
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Administración</p><h1>Auditoría</h1><p>Historial de acciones relevantes del sistema.</p></div><RouterLink class="back-link" to="/panel">Volver al panel</RouterLink></header><form class="filter-form" @submit.prevent="load()"><label>Buscar<input v-model="filters.search" /></label><label>Acción<select v-model="filters.action"><option value="">Todas</option><option v-for="option in data?.action_options" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label>Resultado<select v-model="filters.result"><option value="">Todos</option><option value="exito">Éxito</option><option value="fallo">Fallo</option></select></label><label>Desde<input v-model="filters.from" type="date" /></label><label>Hasta<input v-model="filters.to" type="date" /></label><button>Aplicar</button></form><p v-if="error" role="alert">{{ error }}</p><template v-if="data"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Acción</th><th>Actor</th><th>Recurso</th><th>Resultado</th><th>Detalles</th></tr></thead><tbody><tr v-for="event in data.events.data" :key="event.id"><td>{{ new Date(event.occurred_at).toLocaleString('es-EC') }}</td><td>{{ event.action }}</td><td>{{ event.actor }}<small>{{ event.role }} · {{ event.career }}</small></td><td>{{ event.resource }}</td><td>{{ event.result }}</td><td><span v-for="detail in event.details" :key="detail.label"><strong>{{ detail.label }}:</strong> {{ detail.value }}<br /></span></td></tr></tbody></table></div><PaginationControls :current-page="data.events.current_page" :last-page="data.events.last_page" :total="data.events.total" @change="load" /></template></main></template>
